#!/usr/bin/env python3
"""Regenerates the generated parts of legacy-ciphers/PROOF.bend, in place.

  python3 gen/proof.py           rewrite the regions between the lines
                                 "# BEGIN GENERATED by gen/proof.py: <name>"
                                 and "# END GENERATED: <name>"
  python3 gen/proof.py --check   only check that they are up to date

Five regions:
  "bits"     the lemmas proved by splitting words into their 32 bits (each
             a deep pattern then {==}): rotations and byte swaps undone,
             DES's IP and IP^-1, the low byte of a XOR, a 64-bit block's
             bytes;
  "adc"      a subtraction undoes an addition, and an addition a
             subtraction, for every word (TEA and XTEA), by induction over
             the bits with the carry and the borrow;
  "aria"     ARIA's S-boxes and their inverses on all 256 bytes (each a
             decision tree on the bits), the substitution layers, the round
             key XOR, every elementary step of the diffusion layer and the
             chain of them undone, and a block's bytes read back;
  "serpent"  each S-box and its inverse on all 16 inputs, the S-box layer
             lifted one bit position at a time, and the linear
             transformation undone step by step;
  "vectors"  one {==} proof per vector law, for the vector laws of LAWS.bend.
Everything outside the regions is written by hand.
"""
import os, re, sys

HERE = os.path.dirname(os.path.abspath(__file__))
PKG = os.path.join(HERE, "..")


def word(prefix, n=32):
    s = "WNil{}"
    for i in reversed(range(n)):
        s = "WCon{%s%d, %s}" % (prefix, i, s)
    return s


def u32(prefix):
    return "U32{%s}" % word(prefix)


# ---------------------------------------------------------------- bits

def bits_region():
    out = ["# Rotations and byte swaps undone, for every word: computed on its 32 bits"]
    for a, b in [(1, 31), (31, 1), (19, 13), (13, 19), (29, 3), (3, 29), (25, 7), (7, 25),
                 (27, 5), (5, 27), (10, 22), (22, 10)]:
        out.append("def rot_%d_%d(x: U32) -> {x == L.lc.rotl%d.bits(L.lc.rotl%d.bits(x)) : U32}:\n"
                   "  match x:\n    case %s:\n      {==}" % (a, b, a, b, u32("a")))
    out.append("def bswap2(x: U32) -> {x == L.lc.bswap.bits(L.lc.bswap.bits(x)) : U32}:\n"
               "  match x:\n    case %s:\n      {==}" % u32("a"))
    out.append("# DES's IP and IP^-1 undo each other, computed on the block's 64 bits\n"
               "def des_ip_fp(h: D.LcDesHalves) -> {h == D.des.ip(D.des.fp(h)) : D.LcDesHalves}:\n"
               "  match h:\n    case D.LcDesHalves{%s, %s}:\n      {==}" % (u32("a"), u32("b")))
    out.append("def des_fp_ip(b: L.LcBlock64) -> {b == D.des.fp(D.des.ip(b)) : L.LcBlock64}:\n"
               "  match b:\n    case L.LcBlock64{%s, %s}:\n      {==}" % (u32("a"), u32("b")))
    out.append("# the low byte of a XOR depends only on the low bytes\n"
               "def byte_xor_byte(z: U32, k: U32) -> {B.byte(U32.xor(z, k)) == B.byte(U32.xor(B.byte(z), k)) : U32}:\n"
               "  match z k:\n    case %s %s:\n      {==}" % (u32("a"), u32("b")))
    out.append("# a 64-bit block's bytes, masked and read back\n"
               "def blk_bytes(b: L.LcBlock64) -> {L.lc.block_of(B.mask(L.lc.block_bytes(b, Nil{}))) == Some{b} : Maybe<&2, L.LcBlock64>}:\n"
               "  match b:\n    case L.LcBlock64{%s, %s}:\n      {==}" % (u32("a"), u32("c")))
    bytes8 = ", ".join("B.byte(L.lc.b%d.bits(%s))" % (i, w) for w in ("hi", "lo") for i in range(4))
    out.append("def blk8(hi: U32, lo: U32) -> {L.LcBlock64{hi, lo} == L.lc.block8(%s) : L.LcBlock64}:\n"
               "  match hi lo:\n    case %s %s:\n      {==}" % (bytes8, u32("a"), u32("c")))
    return "\n\n".join(out) + "\n"


# ---------------------------------------------------------------- serpent

def serpent_nib():
    out = ["# the S-box and its inverse undo each other on every 4-bit input\n"]
    bools = ["True{}", "False{}"]
    for bx in range(8):
        for inv in (True, False):
            iv = "True{}" if inv else "False{}"
            nv = "False{}" if inv else "True{}"
            name = "sp_nib_%d_%s" % (bx, "t" if inv else "f")
            o = "P.sp.nib(P.LcSp%d{}, %s, n)" % (bx, iv)
            out.append("def %s(+n: P.LcSpNib) -> {n == P.sp.nib(P.LcSp%d{}, %s, P.LcSpNib{P.sp.na(%s), P.sp.nb(%s), P.sp.nc(%s), P.sp.nd(%s)}) : P.LcSpNib}:" % (name, bx, nv, o, o, o, o))
            out.append("  match n:")
            out.append("    case P.LcSpNib{a, b, c, d}:")
            out.append("      match a b c d:")
            for a in bools:
                for b in bools:
                    for c in bools:
                        for d in bools:
                            out.append("        case %s %s %s %s:" % (a, b, c, d))
                            out.append("          {==}")
            out.append("")
    out.append("def sp_nib_inv(bx: P.LcSpBox, inv: Bool, +n: P.LcSpNib) -> {n == P.sp.nib(bx, Bool.not(inv), P.LcSpNib{P.sp.na(P.sp.nib(bx, inv, n)), P.sp.nb(P.sp.nib(bx, inv, n)), P.sp.nc(P.sp.nib(bx, inv, n)), P.sp.nd(P.sp.nib(bx, inv, n))}) : P.LcSpNib}:")
    out.append("  match bx:")
    for bx in range(8):
        out.append("    case P.LcSp%d{}:" % bx)
        out.append("      match inv:")
        out.append("        case True{}:")
        out.append("          sp_nib_%d_t(n)" % bx)
        out.append("        case False{}:")
        out.append("          sp_nib_%d_f(n)" % bx)
    out.append("")
    return "\n".join(out)


def serpent_layer():
    R = "P.sp.layer(bx, inv, p, P.LcSpQ{t0, t1, t2, t3})"
    RP = "P.sp.layer(bx, Bool.not(inv), p, P.LcSpQ{P.sp.qa(p, %s), P.sp.qb(p, %s), P.sp.qc(p, %s), P.sp.qd(p, %s)})" % (R, R, R, R)
    LHS = "P.LcSpQ{WCon{x0, t0}, WCon{x1, t1}, WCon{x2, t2}, WCon{x3, t3}}"
    R32 = "P.sp.layer(bx, inv, 32n, P.LcSpQ{w0, w1, w2, w3})"
    RR32 = "P.sp.layer(bx, Bool.not(inv), 32n, P.LcSpQ{P.sp.qa(32n, %s), P.sp.qb(32n, %s), P.sp.qc(32n, %s), P.sp.qd(32n, %s)})" % (R32, R32, R32, R32)
    return """
# a layer's input rebuilt from its fields gives the same layer
def sp_eta(+bx: P.LcSpBox, +inv: Bool, -p: Nat, z: P.LcSpQ<p>) -> {P.sp.layer(bx, inv, p, z) == P.sp.layer(bx, inv, p, P.LcSpQ{P.sp.qa(p, z), P.sp.qb(p, z), P.sp.qc(p, z), P.sp.qd(p, z)}) : P.LcSpQ<p>}:
  match z:
    case P.LcSpQ{a, b, c, d}:
      {==}

# an S-box layer and its inverse undo each other on four m-bit words
def sp_layer_inv(+bx: P.LcSpBox, +inv: Bool, m: Nat, +q: P.LcSpQ<m>) -> {q == P.sp.layer(bx, Bool.not(inv), m, P.sp.layer(bx, inv, m, q)) : P.LcSpQ<m>}:
  match m:
    case 0n:
      {==}
    case 1n+(+p):
      match q:
        case P.LcSpQ{WCon{+x0, +t0}, WCon{+x1, +t1}, WCon{+x2, +t2}, WCon{+x3, +t3}}:
          %sp_nib_inv(bx, inv, P.LcSpNib{x0, x1, x2, x3}) : {@LHS == P.LcSpQ{WCon{P.sp.na(_), P.sp.qa(p, @RP)}, WCon{P.sp.nb(_), P.sp.qb(p, @RP)}, WCon{P.sp.nc(_), P.sp.qc(p, @RP)}, WCon{P.sp.nd(_), P.sp.qd(p, @RP)}} : P.LcSpQ<1n+p>}
          %Equal.trans(P.LcSpQ<p>, P.LcSpQ{t0, t1, t2, t3}, P.sp.layer(bx, Bool.not(inv), p, @R), @RP, sp_layer_inv(bx, inv, p, P.LcSpQ{t0, t1, t2, t3}), sp_eta(bx, Bool.not(inv), p, @R)) : {@LHS == P.LcSpQ{WCon{x0, P.sp.qa(p, _)}, WCon{x1, P.sp.qb(p, _)}, WCon{x2, P.sp.qc(p, _)}, WCon{x3, P.sp.qd(p, _)}} : P.LcSpQ<1n+p>}
          {==}

# an S-box step and its inverse undo each other on the state
def sp_sop_inv(+bx: P.LcSpBox, +inv: Bool, s: M.CmBlock) -> {s == P.sp.sop(bx, Bool.not(inv), P.sp.sop(bx, inv, s)) : M.CmBlock}:
  match s:
    case M.CmBlock{U32{+w0}, U32{+w1}, U32{+w2}, U32{+w3}}:
      %Equal.trans(P.LcSpQ<32n>, P.LcSpQ{w0, w1, w2, w3}, P.sp.layer(bx, Bool.not(inv), 32n, @R32), @RR32, sp_layer_inv(bx, inv, 32n, P.LcSpQ{w0, w1, w2, w3}), sp_eta(bx, Bool.not(inv), 32n, @R32)) : {M.CmBlock{U32{w0}, U32{w1}, U32{w2}, U32{w3}} == M.CmBlock{U32{P.sp.qa(32n, _)}, U32{P.sp.qb(32n, _)}, U32{P.sp.qc(32n, _)}, U32{P.sp.qd(32n, _)}} : M.CmBlock}
      {==}
""".replace("@RR32", RR32).replace("@R32", R32).replace("@LHS", LHS).replace("@RP", RP).replace("@R", R)


def serpent_lt():
    out = ["\n# the linear transformation's steps, each undone"]

    def lemma(name, outer, inner, rewrites):
        s = "def %s(s: M.CmBlock) -> {s == P.sp.%s(P.sp.%s(s)) : M.CmBlock}:\n  match s:\n    case M.CmBlock{+x0, +x1, +x2, +x3}:\n" % (name, outer, inner)
        for lem, arg, idx, rest in rewrites:
            h = ["x0", "x1", "x2", "x3"]
            for j, r in rest.items():
                h[j] = r
            h[idx] = "_"
            s += "      %%%s(%s) : {M.CmBlock{x0, x1, x2, x3} == M.CmBlock{%s} : M.CmBlock}\n" % (lem, arg, ", ".join(h))
        s += "      {==}\n"
        out.append(s)

    lemma("sp_lt1", "ilt1", "lt1", [("rot_19_13", "x0", 0, {})])
    lemma("sp_lt1d", "lt1", "ilt1", [("rot_13_19", "x0", 0, {})])
    lemma("sp_lt2", "ilt2", "lt2", [("rot_29_3", "x2", 2, {})])
    lemma("sp_lt2d", "lt2", "ilt2", [("rot_3_29", "x2", 2, {})])
    lemma("sp_lt3", "lt3", "lt3", [("u32_xx", "x1, U32.xor(x0, x2)", 1, {})])
    lemma("sp_lt4", "lt4", "lt4", [("u32_xx", "x3, U32.xor(x2, U32.shln(x0, 3n))", 3, {})])
    lemma("sp_lt5", "ilt5", "lt5", [("rot_31_1", "x1", 1, {3: "L.lc.rotl25.bits(L.lc.rotl7.bits(x3))"}), ("rot_25_7", "x3", 3, {})])
    lemma("sp_lt5d", "lt5", "ilt5", [("rot_1_31", "x1", 1, {3: "L.lc.rotl7.bits(L.lc.rotl25.bits(x3))"}), ("rot_7_25", "x3", 3, {})])
    lemma("sp_lt6", "lt6", "lt6", [("u32_xx", "x0, U32.xor(x1, x3)", 0, {})])
    lemma("sp_lt7", "lt7", "lt7", [("u32_xx", "x2, U32.xor(x3, U32.shln(x1, 7n))", 2, {})])
    lemma("sp_lt8", "ilt8", "lt8", [("rot_27_5", "x0", 0, {2: "L.lc.rotl10.bits(L.lc.rotl22.bits(x2))"}), ("rot_10_22", "x2", 2, {})])
    lemma("sp_lt8d", "lt8", "ilt8", [("rot_5_27", "x0", 0, {2: "L.lc.rotl22.bits(L.lc.rotl10.bits(x2))"}), ("rot_22_10", "x2", 2, {})])

    def nest(fs, inner):
        s = inner
        for f in reversed(fs):
            s = "P.sp.%s(%s)" % (f, s)
        return s

    fwd = ["lt8", "lt7", "lt6", "lt5", "lt4", "lt3", "lt2", "lt1"]
    inv = ["ilt1", "ilt2", "lt3", "lt4", "ilt5", "lt6", "lt7", "ilt8"]
    s = "def sp_lt_inv(+s: M.CmBlock) -> {s == P.sp.ilt(P.sp.lt(s)) : M.CmBlock}:\n"
    lem = ["sp_lt8", "sp_lt7", "sp_lt6", "sp_lt5", "sp_lt4", "sp_lt3", "sp_lt2", "sp_lt1"]
    for i in range(7):
        s += "  %%%s(%s) : {s == %s : M.CmBlock}\n" % (lem[i], nest(fwd[i + 1:], "s"), nest(inv[:7 - i], "_"))
    s += "  sp_lt1(s)\n"
    out.append(s)
    s = "def sp_lt_invd(+s: M.CmBlock) -> {s == P.sp.lt(P.sp.ilt(s)) : M.CmBlock}:\n"
    lemd = ["sp_lt1d", "sp_lt2d", "sp_lt3", "sp_lt4", "sp_lt5d", "sp_lt6", "sp_lt7", "sp_lt8d"]
    for i in range(7):
        s += "  %%%s(%s) : {s == %s : M.CmBlock}\n" % (lemd[i], nest(inv[i + 1:], "s"), nest(fwd[:7 - i], "_"))
    s += "  sp_lt8d(s)\n"
    out.append(s)
    return "\n".join(out)


def serpent_region():
    return serpent_nib() + serpent_layer() + serpent_lt()


# ---------------------------------------------------------------- adc

def adc_region():
    """Word.adc(n, Word.adc(n, a, b, F, c), b, T, not c) == a (a subtraction
    undoes an addition) and the dual, by induction on the bits: in each of
    the eight cases of a's and b's low bits and the carry, the low bit comes
    back and the carry and the borrow stay complementary"""
    def t(v):
        return "True{}" if v else "False{}"
    out = []
    for name, f_in, f_out, flip in (("adc_add_sub", "False{}", "True{}", False), ("adc_sub_add", "True{}", "False{}", True)):
        out.append("def %s(n: Nat, a: Word(n), b: Word(n), c: Bool) -> {a == Word.adc(n, Word.adc(n, a, b, %s, c), b, %s, Bool.not(c)) : Word(n)}:" % (name, f_in, f_out))
        out.append("  match n:\n    case 0n:\n      match a:\n        case WNil{}:\n          {==}\n    case 1n+p:\n      match a b c:")
        for ah in (True, False):
            for bh in (True, False):
                for c in (True, False):
                    b2 = (not bh) if flip else bh
                    k = (ah and b2) or (ah and c) or (b2 and c)
                    out.append("        case WCon{%s, at} WCon{%s, bt} %s:" % (t(ah), t(bh), t(c)))
                    out.append("          %%%s(p, at, bt, %s) : {WCon{%s, at} == WCon{%s, _} : Word(1n+p)}" % (name, t(k), t(ah), t(ah)))
                    out.append("          {==}")
        out.append("")
    out.append("def u32_add_sub(a: U32, b: U32) -> {a == U32.sub(U32.add(a, b), b) : U32}:\n  match a b:\n    case U32{x} U32{y}:\n      %adc_add_sub(32n, x, y, False{}) : {U32{x} == U32{_} : U32}\n      {==}\n")
    out.append("def u32_sub_add(a: U32, b: U32) -> {a == U32.add(U32.sub(a, b), b) : U32}:\n  match a b:\n    case U32{x} U32{y}:\n      %adc_sub_add(32n, x, y, True{}) : {U32{x} == U32{_} : U32}\n      {==}\n")
    return "\n".join(out)


# ---------------------------------------------------------------- aria

sys.path.insert(0, HERE)
import tables as TB  # noqa: E402


def aria_byte_lemma(name, outer, inner):
    """{x == outer(inner(x))} for every byte, by a decision tree on its bits"""
    def tree(d, ind):
        if d == 8:
            return [ind + "match w8:", ind + "  case WNil{}:", ind + "    {==}"]
        out = [ind + "match w%d:" % d]
        for cons in ("False{}", "True{}"):
            out.append(ind + "  case WCon{%s, w%d}:" % (cons, d + 1))
            out += tree(d + 1, ind + "    ")
        return out
    return "def %s(w0: Word(8n)) -> {w0 == A.%s(A.%s(w0)) : Word(8n)}:\n%s\n" % (name, outer, inner, "\n".join(tree(0, "  ")))


def st(fields):
    return "A.LcAriaSt{%s}" % ", ".join(fields)


def rewrite_fields(lemmas, start, lhs):
    """the rewrites turning the fields start back into lhs, one field at a
    time: lemmas[i] (a lemma and its arguments) rewrites field i"""
    out = []
    cur = list(start)
    for i, (lem, arg) in enumerate(lemmas):
        motive = list(cur)
        motive[i] = "_"
        out.append("      %%%s(%s) : {%s == %s : A.LcAriaSt}" % (lem, arg, st(lhs), st(motive)))
        cur[i] = lhs[i]
    return out


def aria_region():
    out = ["# each S-box and its inverse undo each other on every byte"]
    for name, outer, inner in (("aria_sb31", "aria.sb3", "aria.sb1"), ("aria_sb13", "aria.sb1", "aria.sb3"),
                               ("aria_sb42", "aria.sb4", "aria.sb2"), ("aria_sb24", "aria.sb2", "aria.sb4")):
        out.append(aria_byte_lemma(name, outer, inner))
    xs = ["x%d" % i for i in range(16)]
    pat = st(["+" + x for x in xs])
    # SL2 undoes SL1, and SL1 undoes SL2
    sl1 = ["aria.sb1", "aria.sb2", "aria.sb3", "aria.sb4"]
    sl2 = ["aria.sb3", "aria.sb4", "aria.sb1", "aria.sb2"]
    names = {("aria.sb3", "aria.sb1"): "aria_sb31", ("aria.sb1", "aria.sb3"): "aria_sb13",
             ("aria.sb4", "aria.sb2"): "aria_sb42", ("aria.sb2", "aria.sb4"): "aria_sb24"}
    out.append("# SL2 undoes SL1, and SL1 undoes SL2, a byte at a time")
    for lname, outer, inner, on, inn in (("aria_sl21", sl2, sl1, "sl2", "sl1"), ("aria_sl12", sl1, sl2, "sl1", "sl2")):
        body = ["def %s(s: A.LcAriaSt) -> {s == A.aria.%s(A.aria.%s(s)) : A.LcAriaSt}:" % (lname, on, inn),
                "  match s:", "    case %s:" % pat]
        start = ["A.%s(A.%s(x%d))" % (outer[i % 4], inner[i % 4], i) for i in range(16)]
        lemmas = [(names[(outer[i % 4], inner[i % 4])], "x%d" % i) for i in range(16)]
        body += rewrite_fields(lemmas, start, xs)
        body.append("      {==}\n")
        out.append("\n".join(body))
    # the round key XOR undone
    ks = ["k%d" % i for i in range(16)]
    out.append("# a round key XORed twice")
    kq = "M.CmBlock{U32{+k0}, U32{+k1}, U32{+k2}, U32{+k3}}"
    kb = ["A.aria.byte%d(k%d)" % (i % 4, i // 4) for i in range(16)]
    body = ["def aria_xor2(s: A.LcAriaSt, k: M.CmBlock) -> {s == A.aria.xor(A.aria.xor(s, k), k) : A.LcAriaSt}:",
            "  match s k:", "    case %s %s:" % (pat, kq)]
    start = ["Word.xor(8n, Word.xor(8n, x%d, %s), %s)" % (i, kb[i], kb[i]) for i in range(16)]
    body += rewrite_fields([("word_xx", "8n, x%d, %s" % (i, kb[i])) for i in range(16)], start, xs)
    body.append("      {==}\n")
    out.append("\n".join(body))
    # each elementary step of A undone by itself
    out.append("# each elementary step of the diffusion layer is undone by itself")
    for j, (b, ts) in enumerate(TB.ARIA_STEPS):
        body = ["def aria_e%d(s: A.LcAriaSt) -> {s == A.aria.e%d(A.aria.e%d(s)) : A.LcAriaSt}:" % (j, j, j),
                "  match s:", "    case %s:" % pat]
        cur = ["Word.xor(8n, Word.xor(8n, x%d, x%d), x%d)" % (i, b, b) if i in ts else xs[i] for i in range(16)]
        for t in ts:
            motive = list(cur)
            motive[t] = "_"
            body.append("      %%word_xx(8n, x%d, x%d) : {%s == %s : A.LcAriaSt}" % (t, b, st(xs), st(motive)))
            cur[t] = xs[t]
        body.append("      {==}\n")
        out.append("\n".join(body))
    # the chain undone, both ways
    out.append("# the first j steps undone, last first, and the reverse")
    out.append("def aria_d0(s: A.LcAriaSt) -> {s == A.aria.u0(A.aria.d0(s)) : A.LcAriaSt}:\n  {==}\n")
    out.append("def aria_dd0(s: A.LcAriaSt) -> {s == A.aria.d0(A.aria.u0(s)) : A.LcAriaSt}:\n  {==}\n")
    for j in range(len(TB.ARIA_STEPS)):
        out.append("def aria_d%d(+s: A.LcAriaSt) -> {s == A.aria.u%d(A.aria.d%d(s)) : A.LcAriaSt}:\n"
                   "  %%aria_e%d(A.aria.d%d(s)) : {s == A.aria.u%d(_) : A.LcAriaSt}\n  aria_d%d(s)\n" % (j + 1, j + 1, j + 1, j, j, j, j))
        out.append("def aria_dd%d(+s: A.LcAriaSt) -> {s == A.aria.d%d(A.aria.u%d(s)) : A.LcAriaSt}:\n"
                   "  %%aria_dd%d(A.aria.e%d(s)) : {s == A.aria.e%d(_) : A.LcAriaSt}\n  aria_e%d(s)\n" % (j + 1, j + 1, j + 1, j, j, j, j))
    n = len(TB.ARIA_STEPS)
    out.append("def aria_diff(s: A.LcAriaSt) -> {s == A.aria.undiffuse(A.aria.diffuse(s)) : A.LcAriaSt}:\n  aria_d%d(s)\n" % n)
    out.append("def aria_diffd(s: A.LcAriaSt) -> {s == A.aria.diffuse(A.aria.undiffuse(s)) : A.LcAriaSt}:\n  aria_dd%d(s)\n" % n)
    # a block read back from its bytes, and the bytes from their block
    blk = "M.CmBlock{%s}" % ", ".join("U32{%s}" % word("a%d_" % w) for w in range(4))
    out.append("# a block read back from its bytes, and the bytes from their block, on the bits\n"
               "def aria_blk(b: M.CmBlock) -> {b == A.aria.to_block(A.aria.of_block(b)) : M.CmBlock}:\n  match b:\n    case %s:\n      {==}\n" % blk)
    sts = st([word("b%d_" % i, 8) for i in range(16)])
    out.append("def aria_st(s: A.LcAriaSt) -> {s == A.aria.of_block(A.aria.to_block(s)) : A.LcAriaSt}:\n  match s:\n    case %s:\n      {==}\n" % sts)
    return "\n".join(out)


# ---------------------------------------------------------------- vectors

def vectors_region():
    laws = open(os.path.join(PKG, "LAWS.bend"), encoding="utf-8").read()
    start = laws.index("# BEGIN GENERATED by gen/vectors.py: vectors")
    names = re.findall(r"^law (\w+):", laws[start:], re.M)
    return "".join("\ndef Laws.%s():\n  {==}\n" % n for n in names)


REGIONS = {"bits": bits_region, "serpent": serpent_region, "adc": adc_region, "aria": aria_region,
           "vectors": vectors_region}


def main():
    path = os.path.join(PKG, "PROOF.bend")
    with open(path, encoding="utf-8", newline="") as f:
        src = f.read()
    new = src
    for name, body in REGIONS.items():
        begin = "# BEGIN GENERATED by gen/proof.py: %s\n" % name
        end = "# END GENERATED: %s\n" % name
        i = new.index(begin) + len(begin)
        j = new.index(end, i)
        new = new[:i] + body() + new[j:]
    if "--check" in sys.argv[1:]:
        if new != src:
            print("PROOF.bend differs from what gen/proof.py generates")
            sys.exit(1)
        print("PROOF.bend is up to date")
        return
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        f.write(new)


main()
